/**
 * Parser and normalizer for compaction model responses.
 */

import { generateRandomId } from "../core/id.js";

/**
 * A group of related decisions inside a compacted trajectory.
 */
export interface DecisionGroup {
  category: string;
  decisions: Array<{
    question: string;
    chosen: string;
    reasoning: string;
    fromTrajectory: string;
  }>;
}

/**
 * Compacted trajectory summary generated by the model.
 */
export interface CompactedTrajectory {
  id: string;
  version: 1;
  type: "compacted";
  compactedAt: string;
  sourceTrajectories: string[];
  dateRange: {
    start: string;
    end: string;
  };
  summary: {
    totalDecisions: number;
    totalEvents: number;
    uniqueAgents: string[];
  };
  decisionGroups: DecisionGroup[];
  keyLearnings: string[];
  keyFindings: string[];
  filesAffected: string[];
  commits: string[];
}

/**
 * Parse a raw LLM response into a normalized compacted trajectory.
 */
export function parseCompactionResponse(raw: string): CompactedTrajectory {
  const input = raw.trim();
  if (!input) {
    throw new Error("Compaction response is empty.");
  }

  const candidates = collectJsonCandidates(input);
  const parseErrors: string[] = [];

  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      return normalizeCompactedTrajectory(parsed);
    } catch (error) {
      parseErrors.push(error instanceof Error ? error.message : String(error));
    }
  }

  throw new Error(
    [
      "Failed to parse compaction response as JSON.",
      parseErrors[0] ? `First parse error: ${parseErrors[0]}` : undefined,
    ]
      .filter(Boolean)
      .join(" "),
  );
}

function collectJsonCandidates(raw: string): string[] {
  const candidates: string[] = [];
  const seen = new Set<string>();

  pushCandidate(candidates, seen, raw);

  const codeBlockPattern = /```(?:json)?\s*([\s\S]*?)```/gi;
  for (const match of raw.matchAll(codeBlockPattern)) {
    pushCandidate(candidates, seen, match[1]);
  }

  const regexCandidate = raw.match(/\{[\s\S]*\}/)?.[0];
  pushCandidate(candidates, seen, regexCandidate);

  const balancedCandidate = extractBalancedObject(raw);
  pushCandidate(candidates, seen, balancedCandidate);

  return candidates;
}

function pushCandidate(
  candidates: string[],
  seen: Set<string>,
  value?: string | null,
): void {
  const normalized = value?.trim();
  if (!normalized || seen.has(normalized)) {
    return;
  }

  seen.add(normalized);
  candidates.push(normalized);
}

function extractBalancedObject(raw: string): string | null {
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;

  for (let index = 0; index < raw.length; index++) {
    const char = raw[index];

    if (inString) {
      if (escaped) {
        escaped = false;
        continue;
      }
      if (char === "\\") {
        escaped = true;
        continue;
      }
      if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === "{") {
      if (depth === 0) {
        start = index;
      }
      depth += 1;
      continue;
    }

    if (char === "}") {
      depth -= 1;
      if (depth === 0 && start >= 0) {
        return raw.slice(start, index + 1);
      }
    }
  }

  return null;
}

function normalizeCompactedTrajectory(input: unknown): CompactedTrajectory {
  if (!isRecord(input)) {
    throw new Error("Compaction response must be a JSON object.");
  }

  const decisionGroups = normalizeDecisionGroups(input.decisionGroups);
  const inferredSourceTrajectories = new Set<string>();
  for (const group of decisionGroups) {
    for (const decision of group.decisions) {
      if (decision.fromTrajectory) {
        inferredSourceTrajectories.add(decision.fromTrajectory);
      }
    }
  }

  const providedSourceTrajectories = asStringArray(input.sourceTrajectories);
  for (const source of providedSourceTrajectories) {
    inferredSourceTrajectories.add(source);
  }

  const summary = isRecord(input.summary) ? input.summary : {};
  const now = new Date().toISOString();
  const defaultId = `compact_${generateRandomId()}`;
  const totalDecisions = decisionGroups.reduce(
    (sum, group) => sum + group.decisions.length,
    0,
  );

  if (
    decisionGroups.length === 0 &&
    inferredSourceTrajectories.size === 0 &&
    asStringArray(input.keyLearnings).length === 0 &&
    asStringArray(input.keyFindings).length === 0
  ) {
    throw new Error(
      "Compaction response is missing all expected summary fields.",
    );
  }

  return {
    id: asNonEmptyString(input.id) || defaultId,
    version: 1,
    type: "compacted",
    compactedAt: asIsoString(input.compactedAt) || now,
    sourceTrajectories: [...inferredSourceTrajectories],
    dateRange: normalizeDateRange(input.dateRange, now),
    summary: {
      totalDecisions,
      totalEvents: asNumber(summary.totalEvents) ?? 0,
      uniqueAgents: asStringArray(summary.uniqueAgents),
    },
    decisionGroups,
    keyLearnings: asStringArray(input.keyLearnings),
    keyFindings: asStringArray(input.keyFindings),
    filesAffected: asStringArray(input.filesAffected),
    commits: asStringArray(input.commits),
  };
}

function normalizeDateRange(
  value: unknown,
  fallbackDate: string,
): { start: string; end: string } {
  if (!isRecord(value)) {
    return { start: fallbackDate, end: fallbackDate };
  }

  return {
    start: asIsoString(value.start) || fallbackDate,
    end: asIsoString(value.end) || asIsoString(value.start) || fallbackDate,
  };
}

function normalizeDecisionGroups(value: unknown): DecisionGroup[] {
  if (!Array.isArray(value)) {
    return [];
  }

  const groups: DecisionGroup[] = [];

  for (const entry of value) {
    if (!isRecord(entry)) {
      continue;
    }

    const decisionsValue = Array.isArray(entry.decisions)
      ? entry.decisions
      : [];
    const decisions: DecisionGroup["decisions"] = [];

    for (const decisionEntry of decisionsValue) {
      if (!isRecord(decisionEntry)) {
        continue;
      }

      const question = asNonEmptyString(decisionEntry.question);
      const chosen = asNonEmptyString(decisionEntry.chosen);
      const reasoning = asNonEmptyString(decisionEntry.reasoning);

      if (!question || !chosen || !reasoning) {
        continue;
      }

      decisions.push({
        question,
        chosen,
        reasoning,
        fromTrajectory:
          asNonEmptyString(decisionEntry.fromTrajectory) || "unknown",
      });
    }

    groups.push({
      category: asNonEmptyString(entry.category) || "other",
      decisions,
    });
  }

  return groups;
}

function asStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((entry) => asNonEmptyString(entry))
    .filter((entry): entry is string => Boolean(entry));
}

function asIsoString(value: unknown): string | null {
  const stringValue = asNonEmptyString(value);
  if (!stringValue) {
    return null;
  }

  const timestamp = Date.parse(stringValue);
  return Number.isNaN(timestamp) ? null : new Date(timestamp).toISOString();
}

function asNonEmptyString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function asNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
